  RETURN c.key_id IS NOT NULL AND c.key_id ~ '^[A-Za-z0-9._-]{1,128}$'
    AND c.iv IS NOT NULL AND octet_length(c.iv)=12 AND c.tag IS NOT NULL AND octet_length(c.tag)=16
